cd /home/axel/LeanAlgebraicGeometry-Horizon
python3 - <<'EOF'
import yaml,glob
print("=== TASKS ===")
for f in sorted(glob.glob('.archon-horizon/tasks/items/*.yaml')):
    d=yaml.safe_load(open(f)); md=d.get('metadata') or {}
    if d.get('status') in ('queued','running'):
        print(f"{d['id']:<18} {d.get('status'):<8} created={md.get('created_at')} upd={md.get('updated_at')} refs={len(d.get('roadmap_refs') or [])}")
print()
print("=== ACTIVE ROADMAP ===")
for f in sorted(glob.glob('.archon-horizon/roadmap/items/*.yaml')):
    d=yaml.safe_load(open(f)); md=d.get('metadata') or {}
    if d.get('status')=='active':
        print(f"{d['id']:<62} owner={md.get('owner')} ms={md.get('milestone')} upd={md.get('updated_at')}")
EOF

